    public async ValueTask<FieldRelayEncounter?> EncounterAsync()=>Read<FieldRelayEncounter>(await _repository.SnapshotAsync(),CombatId);
    public async ValueTask<CommandResult> BeginEncounterAsync(string difficulty="standard",string[]? supplies=null)
