        var s=await _repository.SnapshotAsync();Allowed(s);var st=State(s);Require(!st.ThreatControlled&&!BranchOperations.Receipt(s,"R6:"+Encounter+":result"),"已有实际制止结果，不重刷同一机卫。");var old=Read<FieldRelayEncounter>(s,CombatId);Require(old is null||old.Battle.Outcome==CombatOutcome.Withdrawn,"当前尝试须继续或先从同入口撤回。");var party=new PartyService(_repository,_catalog);var hero=party.Inspect(s);Require(hero.Grade==3&&hero.Level>=25,"这份可选现场范围继承真实Q603后的成长，不预支最后校准。");var equipped=s.Items.Where(i=>i.OwnerKind=="equipped"&&i.OwnerId=="hero").ToArray();var modules=s.Items.Where(i=>i.OwnerKind=="module_installed"&&equipped.Any(eq=>eq.Id==i.OwnerId)).Select(i=>party.Definitions.Modules[i.DefinitionId]);var roster=new RosterService(_repository,_catalog);var helpers=roster.Helpers(s);var battle=BattleDefinitions.Create("BENCH-WORKSHOP",hero.Level,hero.Grade,hero.Build,hero.Weapon,hero.Armor,hero.Relics,modules,st.Instance,Guid.NewGuid(),difficulty,helpers.ToArray());battle.Definition=Encounter;battle.Mechanism=null;battle.Controls.Clear();battle.Units.RemoveAll(u=>u.Side==CombatSide.Enemy);
        foreach(var helper in battle.Units.Where(u=>u.Id.StartsWith("CP-",StringComparison.Ordinal)))
