        using var modes=JsonDocument.Parse(_catalog.Definitions["combat_difficulty"][0].PayloadJson);int hpBp=modes.RootElement.EnumerateArray().Single(m=>m.GetProperty("id").GetString()==difficulty).GetProperty("enemy_hp_bp").GetInt32();int hp=360*hpBp/10000;battle.Units.Add(new(){Id="r6-aux-relay-drone",Name="外线辅助继电机卫",Side=CombatSide.Enemy,Slot=0,MaxHp=hp,Hp=hp,ArmorBp=800,PressureThreshold=3,Initiative=14,Pattern=[new("辅机跟踪冲击",95,TargetLock.Unit,true,true),new("导轨复位准备",0,TargetLock.Unit,false,true)]});supplies??=[];Require(supplies.Length<=2&&supplies.Distinct().Count()==supplies.Length,"最多两份不同的实际增强补给。");foreach(string id in supplies){var i=s.Items.SingleOrDefault(i=>i.Id==id&&i.OwnerKind=="player"&&i.OwnerId=="hero"&&i.DefinitionId is "CON-01" or "CON-02" or "CON-03" or "CON-04")??throw new InvalidOperationException("增强补给未实际持有。");battle.Supplies.Add(new(i.Id,i.DefinitionId));}var entry=StrictJson.Deserialize<BattleSnapshot>(StrictJson.Serialize(battle));var engine=new BattleEngine(BattleDefinitions,battle);engine.Start();return await Execute(Plan(s,StateId+":battle:"+battle.Attempt+":entry","field_relay_encounter_entered",new{encounter=Encounter,instance=battle.Instance,attempt=battle.Attempt,actual_level=hero.Level,actual_grade=hero.Grade,numeric_status="original_unreviewed_human_pending",kill_xp=0},[BranchOperations.Change(s,CombatId,"combat",new FieldRelayEncounter(engine.Snapshot(),entry,Actor(s)))]));
    }
    public async ValueTask<EncounterActionPreview> PreviewActionAsync(BattleRequest request)
    {
        var s=await _repository.SnapshotAsync();Allowed(s,true);var st=State(s);var old=Read<FieldRelayEncounter>(s,CombatId)??throw new InvalidOperationException("实际辅机遭遇尚未进入。");Require(old.Battle.Definition==Encounter&&old.Battle.Instance==st.Instance&&Actor(s)==old.ReturnActor,"当前辅机、实例或实际入口改变。");var engine=new BattleEngine(BattleDefinitions,old.Battle);var preview=engine.Preview(request);if(!preview.Legal)return new(Guid.Empty,preview,preview.Reason??"行动不可执行。");engine.Apply(request);var battle=engine.Snapshot();var changes=ImmutableArray.CreateBuilder<EntityChange>();var items=ImmutableArray.CreateBuilder<ItemChange>();string action="field_relay_combat_action",key=StateId+":battle:"+battle.Attempt+":"+request.Command.Value;object payload=new{request,outcome=battle.Outcome,kill_xp=0};if(battle.Outcome==CombatOutcome.Controlled&&!st.ThreatControlled){var result=new FrontierEncounterResult(Encounter,true,battle.Instance,battle.Attempt,"shared_combat_auxiliary_only",st.Configuration);changes.Add(BranchOperations.Change(s,"R6:result:"+Encounter,"chapter_encounter_result",result));changes.Add(BranchOperations.Change(s,StateId,"optional_field_repair",st with{ThreatControlled=true}));action="chapter_six_encounter_result";key="R6:"+Encounter+":result";payload=result;}foreach(var used in battle.Supplies.Where(i=>i.Used&&!old.Battle.Supplies.Single(x=>x.Instance==i.Instance).Used)){var i=s.Items.Single(i=>i.Id==used.Instance&&i.OwnerKind=="player"&&i.OwnerId=="hero");items.Add(new(i.Id,i.DefinitionId,i.OwnerKind,i.OwnerId,"consumed",battle.Attempt.ToString(),null));}changes.Add(BranchOperations.Change(s,CombatId,"combat",old with{Battle=battle}));var c=Plan(s,key,action,payload,changes.ToImmutable(),items.ToImmutable(),request.Command);Guid token=Guid.NewGuid();_previews[token]=c;return new(token,preview,$"{request.Actor} · {request.Action} · AP {preview.Ap} / 专注 {preview.Focus}");
    }
    public ValueTask<CommandResult> ConfirmPreviewAsync(Guid token)=>_previews.TryGetValue(token,out var c)?Execute(c):ValueTask.FromResult(new CommandResult(CommitStatus.Rejected,null,[new("preview_closed",StateId,"辅机战斗预览已关闭。") ]));
    public void ClosePreview(Guid token)=>_previews.Remove(token);
    public async ValueTask<CommandResult> WithdrawEncounterAsync()
    {var s=await _repository.SnapshotAsync();Allowed(s,true);var st=State(s);var old=Read<FieldRelayEncounter>(s,CombatId)??throw new InvalidOperationException("实际遭遇尚未进入。");Require(!st.ThreatControlled&&!BranchOperations.Receipt(s,"R6:"+Encounter+":result"),"已接受制止结果不撤回重刷。");var entry=StrictJson.Deserialize<BattleSnapshot>(StrictJson.Serialize(old.Entry));entry.Outcome=CombatOutcome.Withdrawn;entry.CurrentActor=null;var items=old.Battle.Supplies.Where(x=>x.Used).Select(x=>{var i=s.Items.Single(i=>i.Id==x.Instance&&i.OwnerKind=="consumed"&&i.OwnerId==old.Battle.Attempt.ToString());return new ItemChange(i.Id,i.DefinitionId,i.OwnerKind,i.OwnerId,"player","hero",null);}).ToImmutableArray();_previews.Clear();return await Execute(Plan(s,StateId+":battle:"+old.Battle.Attempt+":withdraw","field_relay_encounter_withdrawn",new{encounter=Encounter,outside_physical_steps_retained=true,main_work_unchanged=true},[BranchOperations.Change(s,CombatId,"combat",old with{Battle=entry}),BranchOperations.Change(s,"actor","actor",old.ReturnActor)],items));}
